import { describe, expect, it } from 'vitest'

import { progress } from '../../../../src/todos/application/progress'
import type { TodoViewModel } from '../../../../src/todos/application/TodoViewModel'

const todo = (id: string, status: TodoViewModel['status']): TodoViewModel => ({
  id,
  title: `Todo ${id}`,
  status,
})

describe('progress', () => {
  it('should say there is nothing to do for an empty list', () => {
    expect(progress([])).toBe('Nothing to do')
  })

  it('should say all done when every todo is done', () => {
    expect(progress([todo('1', 'done'), todo('2', 'done')])).toBe('All done')
  })

  it('should count the done todos when some are open', () => {
    expect(progress([todo('1', 'done'), todo('2', 'open'), todo('3', 'open')])).toBe('1 of 3 done')
  })

  it('should report none done when all are open', () => {
    expect(progress([todo('1', 'open'), todo('2', 'open')])).toBe('0 of 2 done')
  })
})
EOF
